### Lab 2: Creating Custom IAM Policies

**Objective:** Create fine-grained custom policies following least privilege principle.

#### Scenario 1: S3 Developer Policy

Allow developers to manage objects in specific S3 buckets but not modify bucket configuration:

```bash
# Create policy document
cat > s3-developer-policy.json <<'EOF'
{
  "Version": "2012-10-17",
  "Statement": [
    {
      "Sid": "ListAllBuckets",
      "Effect": "Allow",
      "Action": "s3:ListAllMyBuckets",
      "Resource": "*"
    },
    {
      "Sid": "ManageDevBuckets",
      "Effect": "Allow",
      "Action": [
        "s3:ListBucket",
        "s3:GetBucketLocation"
      ],
      "Resource": [
        "arn:aws:s3:::dev-application-*",
        "arn:aws:s3:::staging-application-*"
      ]
    },
    {
      "Sid": "ManageObjects",
      "Effect": "Allow",
      "Action": [
        "s3:GetObject",
        "s3:PutObject",
        "s3:DeleteObject",
        "s3:GetObjectVersion"
      ],
      "Resource": [
        "arn:aws:s3:::dev-application-*/*",
        "arn:aws:s3:::staging-application-*/*"
      ]
    },
    {
      "Sid": "DenyProductionBuckets",
      "Effect": "Deny",
      "Action": "s3:*",
      "Resource": [
        "arn:aws:s3:::prod-application-*",
        "arn:aws:s3:::prod-application-*/*"
      ]
    }
  ]
}
EOF

# Create the policy
aws iam create-policy \
    --policy-name S3DeveloperAccess \
    --policy-document file://s3-developer-policy.json \
    --description "Allow developers to manage dev/staging S3 buckets"

# Attach to developers group
aws iam attach-group-policy \
    --group-name developers \
    --policy-arn arn:aws:iam::123456789012:policy/S3DeveloperAccess
```


#### Scenario 2: EC2 Management with Tag-Based Access

Allow users to manage only EC2 instances tagged with their team:

```bash
cat > ec2-team-policy.json <<'EOF'
{
  "Version": "2012-10-17",
  "Statement": [
    {
      "Sid": "ViewAllInstances",
      "Effect": "Allow",
      "Action": [
        "ec2:Describe*",
        "ec2:Get*"
      ],
      "Resource": "*"
    },
    {
      "Sid": "ManageTeamInstances",
      "Effect": "Allow",
      "Action": [
        "ec2:StartInstances",
        "ec2:StopInstances",
        "ec2:RebootInstances",
        "ec2:TerminateInstances"
      ],
      "Resource": "arn:aws:ec2:*:*:instance/*",
      "Condition": {
        "StringEquals": {
          "ec2:ResourceTag/Team": "${aws:PrincipalTag/Team}"
        }
      }
    },
    {
      "Sid": "RequireTeamTagOnCreate",
      "Effect": "Allow",
      "Action": "ec2:RunInstances",
      "Resource": "arn:aws:ec2:*:*:instance/*",
      "Condition": {
        "StringEquals": {
          "aws:RequestTag/Team": "${aws:PrincipalTag/Team}"
        }
      }
    },
    {
      "Sid": "AllowLaunchTemplate",
      "Effect": "Allow",
      "Action": "ec2:RunInstances",
      "Resource": [
        "arn:aws:ec2:*:*:network-interface/*",
        "arn:aws:ec2:*:*:subnet/*",
        "arn:aws:ec2:*:*:volume/*",
        "arn:aws:ec2:*:*:security-group/*",
        "arn:aws:ec2:*::image/*"
      ]
    }
  ]
}
EOF

aws iam create-policy \
    --policy-name EC2TeamBasedAccess \
    --policy-document file://ec2-team-policy.json
```

**Tag the user:**

```bash
aws iam tag-user \
    --user-name alice \
    --tags Key=Team,Value=backend
```

Now Alice can only manage EC2 instances tagged with `Team=backend`.

#### Scenario 3: Time-Based Access Control

Grant access only during business hours:

```bash
cat > business-hours-policy.json <<'EOF'
{
  "Version": "2012-10-17",
  "Statement": [
    {
      "Sid": "AllowDuringBusinessHours",
      "Effect": "Allow",
      "Action": "rds:*",
      "Resource": "*",
      "Condition": {
        "DateGreaterThan": {
          "aws:CurrentTime": "2025-01-01T09:00:00Z"
        },
        "DateLessThan": {
          "aws:CurrentTime": "2025-12-31T18:00:00Z"
        },
        "StringEquals": {
          "aws:RequestedRegion": "us-east-1"
        }
      }
    }
  ]
}
EOF

aws iam create-policy \
    --policy-name BusinessHoursRDSAccess \
    --policy-document file://business-hours-policy.json
```

### Lab 3: Implementing Blue-Green Deployment on ECS

**Objective:** Zero-downtime deployment using CodeDeploy blue-green strategy.

```bash
# Update task definition with new image version
# taskdef-v2.json with image:v2.0.0

# Create CodeDeploy application
aws deploy create-application \
    --application-name myapp-ecs \
    --compute-platform ECS

# Create deployment group
aws deploy create-deployment-group \
    --application-name myapp-ecs \
    --deployment-group-name myapp-dg \
    --service-role-arn arn:aws:iam::123456789012:role/CodeDeployServiceRole \
    --ecs-services clusterName=production-cluster,serviceName=myapp-service \
    --load-balancer-info "targetGroupPairInfoList=[{
      targetGroups=[
        {name=myapp-blue-tg},
        {name=myapp-green-tg}
      ],
      prodTrafficRoute={listenerArns=[arn:aws:elasticloadbalancing:us-east-1:123456789012:listener/app/myapp-alb/...]},
      testTrafficRoute={listenerArns=[arn:aws:elasticloadbalancing:us-east-1:123456789012:listener/app/myapp-alb/...]}
    }]" \
    --deployment-style "deploymentType=BLUE_GREEN,deploymentOption=WITH_TRAFFIC_CONTROL" \
    --blue-green-deployment-configuration '{
      "terminateBlueInstancesOnDeploymentSuccess": {
        "action": "TERMINATE",
        "terminationWaitTimeInMinutes": 5
      },
      "deploymentReadyOption": {
        "actionOnTimeout": "CONTINUE_DEPLOYMENT"
      }
    }'

# Create deployment
aws deploy create-deployment \
    --application-name myapp-ecs \
    --deployment-group-name myapp-dg \
    --revision '{
      "revisionType": "AppSpecContent",
      "appSpecContent": {
        "content": "{\"version\":1,\"Resources\":[{\"TargetService\":{\"Type\":\"AWS::ECS::Service\",\"Properties\":{\"TaskDefinition\":\"'$TASK_DEF_ARN'\",\"LoadBalancerInfo\":{\"ContainerName\":\"web\",\"ContainerPort\":3000}}}}]}"
      }
    }'
```

### Lab 1: Creating and Configuring S3 Buckets

**Objective:** Create production-ready S3 bucket with security and lifecycle policies.

#### Step 1: Create Bucket with Security Settings

```bash
# Create bucket
aws s3api create-bucket \
    --bucket my-production-bucket-$(date +%s) \
    --region us-east-1 \
    --object-ownership BucketOwnerEnforced

BUCKET_NAME="my-production-bucket-1234567890"

# Enable versioning
aws s3api put-bucket-versioning \
    --bucket $BUCKET_NAME \
    --versioning-configuration Status=Enabled

# Enable default encryption (SSE-S3)
aws s3api put-bucket-encryption \
    --bucket $BUCKET_NAME \
    --server-side-encryption-configuration '{
      "Rules": [{
        "ApplyServerSideEncryptionByDefault": {
          "SSEAlgorithm": "AES256"
        },
        "BucketKeyEnabled": true
      }]
    }'

# Block all public access
aws s3api put-public-access-block \
    --bucket $BUCKET_NAME \
    --public-access-block-configuration \
        BlockPublicAcls=true,\
        IgnorePublicAcls=true,\
        BlockPublicPolicy=true,\
        RestrictPublicBuckets=true

# Enable logging
aws s3api put-bucket-logging \
    --bucket $BUCKET_NAME \
    --bucket-logging-status '{
      "LoggingEnabled": {
        "TargetBucket": "my-logs-bucket",
        "TargetPrefix": "s3-access-logs/"
      }
    }'

# Enable versioning
aws s3api put-bucket-versioning \
    --bucket $BUCKET_NAME \
    --versioning-configuration Status=Enabled

# Add tags
aws s3api put-bucket-tagging \
    --bucket $BUCKET_NAME \
    --tagging 'TagSet=[
      {Key=Environment,Value=Production},
      {Key=CostCenter,Value=Engineering},
      {Key=DataClassification,Value=Confidential}
    ]'
```


#### Step 2: Configure Lifecycle Policy

```bash
cat > lifecycle-policy.json <<'EOF'
{
  "Rules": [
    {
      "Id": "Transition-Archive-Delete",
      "Status": "Enabled",
      "Filter": {
        "Prefix": "data/"
      },
      "Transitions": [
        {
          "Days": 30,
          "StorageClass": "STANDARD_IA"
        },
        {
          "Days": 90,
          "StorageClass": "INTELLIGENT_TIERING"
        },
        {
          "Days": 365,
          "StorageClass": "GLACIER_IR"
        }
      ],
      "Expiration": {
        "Days": 2555
      }
    },
    {
      "Id": "Delete-Old-Versions",
      "Status": "Enabled",
      "NoncurrentVersionTransitions": [
        {
          "NoncurrentDays": 30,
          "StorageClass": "STANDARD_IA"
        },
        {
          "NoncurrentDays": 90,
          "StorageClass": "GLACIER_FLEXIBLE_RETRIEVAL"
        }
      ],
      "NoncurrentVersionExpiration": {
        "NoncurrentDays": 180
      }
    },
    {
      "Id": "Cleanup-Incomplete-Multipart",
      "Status": "Enabled",
      "AbortIncompleteMultipartUpload": {
        "DaysAfterInitiation": 7
      }
    },
    {
      "Id": "Delete-Expired-DeleteMarkers",
      "Status": "Enabled",
      "Expiration": {
        "ExpiredObjectDeleteMarker": true
      }
    }
  ]
}
EOF

aws s3api put-bucket-lifecycle-configuration \
    --bucket $BUCKET_NAME \
    --lifecycle-configuration file://lifecycle-policy.json
```


#### Step 3: Configure Bucket Policy

```bash
cat > bucket-policy.json <<EOF
{
  "Version": "2012-10-17",
  "Statement": [
    {
      "Sid": "EnforceSSLOnly",
      "Effect": "Deny",
      "Principal": "*",
      "Action": "s3:*",
      "Resource": [
        "arn:aws:s3:::$BUCKET_NAME",
        "arn:aws:s3:::$BUCKET_NAME/*"
      ],
      "Condition": {
        "Bool": {
          "aws:SecureTransport": "false"
        }
      }
    },
    {
      "Sid": "DenyUnencryptedObjectUploads",
      "Effect": "Deny",
      "Principal": "*",
      "Action": "s3:PutObject",
      "Resource": "arn:aws:s3:::$BUCKET_NAME/*",
      "Condition": {
        "StringNotEquals": {
          "s3:x-amz-server-side-encryption": "AES256"
        }
      }
    },
    {
      "Sid": "AllowApplicationAccess",
      "Effect": "Allow",
      "Principal": {
        "AWS": "arn:aws:iam::123456789012:role/MyApplicationRole"
      },
      "Action": [
        "s3:GetObject",
        "s3:PutObject",
        "s3:DeleteObject"
      ],
      "Resource": "arn:aws:s3:::$BUCKET_NAME/*"
    }
  ]
}
EOF

aws s3api put-bucket-policy \
    --bucket $BUCKET_NAME \
    --policy file://bucket-policy.json
```

### Lab 3: S3 Batch Operations

**Objective:** Process millions of objects using S3 Batch Operations.

```python
# create_batch_job.py
import boto3
import json

s3control = boto3.client('s3control')
s3 = boto3.client('s3')

def create_inventory():
    """
    Create S3 inventory to list all objects
    Required for batch operations
    """

    bucket = 'my-source-bucket'
    inventory_bucket = 'my-inventory-bucket'

    inventory_config = {
        'Destination': {
            'S3BucketDestination': {
                'AccountId': '123456789012',
                'Bucket': f'arn:aws:s3:::{inventory_bucket}',
                'Format': 'CSV',
                'Prefix': 'inventory'
            }
        },
        'IsEnabled': True,
        'Id': 'EntireBucketInventory',
        'IncludedObjectVersions': 'Current',
        'OptionalFields': [
            'Size', 'LastModifiedDate', 'StorageClass',
            'ETag', 'IsMultipartUploaded', 'ReplicationStatus'
        ],
        'Schedule': {
            'Frequency': 'Daily'
        }
    }

    s3.put_bucket_inventory_configuration(
        Bucket=bucket,
        Id='EntireBucketInventory',
        InventoryConfiguration=inventory_config
    )

    print("Inventory configuration created. First report available in 24-48 hours.")

def create_batch_copy_job(manifest_location):
    """
    Create batch job to copy objects to different storage class
    """

    account_id = '123456789012'
    role_arn = 'arn:aws:iam::123456789012:role/S3BatchOperationsRole'

    response = s3control.create_job(
        AccountId=account_id,
        ConfirmationRequired=False,
        Operation={
            'S3PutObjectCopy': {
                'TargetResource': 'arn:aws:s3:::destination-bucket',
                'StorageClass': 'GLACIER_IR',
                'MetadataDirective': 'COPY',
                'TargetKeyPrefix': 'archived/'
            }
        },
        Report={
            'Bucket': 'arn:aws:s3:::my-reports-bucket',
            'Format': 'Report_CSV_20180820',
            'Enabled': True,
            'Prefix': 'batch-reports',
            'ReportScope': 'AllTasks'
        },
        Manifest={
            'Spec': {
                'Format': 'S3InventoryReport_CSV_20161130',
                'Fields': ['Bucket', 'Key']
            },
            'Location': {
                'ObjectArn': manifest_location,
                'ETag': 'manifest-etag'
            }
        },
        Priority=10,
        RoleArn=role_arn,
        Tags=[
            {'Key': 'Project', 'Value': 'DataArchival'},
            {'Key': 'Environment', 'Value': 'Production'}
        ]
    )

    job_id = response['JobId']
    print(f"Batch job created: {job_id}")

    return job_id

def create_batch_tagging_job(manifest_location):
    """
    Create batch job to add tags to millions of objects
    """

    account_id = '123456789012'
    role_arn = 'arn:aws:iam::123456789012:role/S3BatchOperationsRole'

    response = s3control.create_job(
        AccountId=account_id,
        ConfirmationRequired=True,  # Require confirmation before running
        Operation={
            'S3PutObjectTagging': {
                'TagSet': [
                    {'Key': 'Project', 'Value': 'DataLake'},
                    {'Key': 'Classification', 'Value': 'Internal'},
                    {'Key': 'RetentionPolicy', 'Value': '7years'}
                ]
            }
        },
        Report={
            'Bucket': 'arn:aws:s3:::my-reports-bucket',
            'Format': 'Report_CSV_20180820',
            'Enabled': True,
            'Prefix': 'tagging-reports'
        },
        Manifest={
            'Spec': {
                'Format': 'S3BatchOperations_CSV_20180820',
                'Fields': ['Bucket', 'Key']
            },
            'Location': {
                'ObjectArn': manifest_location,
                'ETag': 'manifest-etag'
            }
        },
        Priority=5,
        RoleArn=role_arn
    )

    return response['JobId']

# Monitor batch job
def monitor_job(job_id):
    """Monitor batch job progress"""

    account_id = '123456789012'

    response = s3control.describe_job(
        AccountId=account_id,
        JobId=job_id
    )

    job = response['Job']

    print(f"Job Status: {job['Status']}")
    print(f"Progress: {job['ProgressSummary']}")

    return job['Status']
```

### Lab 2: Snapshot Automation with Data Lifecycle Manager

**Objective:** Automate EBS snapshot lifecycle management.

```bash
# Create DLM policy
cat > dlm-policy.json <<'EOF'
{
  "PolicyDetails": {
    "PolicyType": "EBS_SNAPSHOT_MANAGEMENT",
    "ResourceTypes": ["VOLUME"],
    "TargetTags": [
      {
        "Key": "Backup",
        "Value": "Daily"
      }
    ],
    "Schedules": [
      {
        "Name": "Daily snapshots",
        "CopyTags": true,
        "TagsToAdd": [
          {
            "Key": "SnapshotType",
            "Value": "DLM-Daily"
          }
        ],
        "CreateRule": {
          "Interval": 24,
          "IntervalUnit": "HOURS",
          "Times": ["03:00"]
        },
        "RetainRule": {
          "Count": 30
        },
        "FastRestoreRule": {
          "AvailabilityZones": ["us-east-1a"],
          "Count": 1
        },
        "CrossRegionCopyRules": [
          {
            "TargetRegion": "us-west-2",
            "Encrypted": true,
            "RetainRule": {
              "Interval": 7,
              "IntervalUnit": "DAYS"
            }
          }
        ]
      },
      {
        "Name": "Weekly snapshots",
        "CreateRule": {
          "CronExpression": "cron(0 2 ? * SUN *)"
        },
        "RetainRule": {
          "Count": 12
        }
      }
    ]
  },
  "Description": "Automated daily and weekly backups",
  "State": "ENABLED",
  "ExecutionRoleArn": "arn:aws:iam::123456789012:role/AWSDataLifecycleManagerDefaultRole"
}
EOF

# Create DLM lifecycle policy
POLICY_ID=$(aws dlm create-lifecycle-policy \
    --cli-input-json file://dlm-policy.json \
    --query 'PolicyId' \
    --output text)

echo "DLM Policy ID: $POLICY_ID"

# Tag volumes for automatic backup
aws ec2 create-tags \
    --resources $VOLUME_ID \
    --tags Key=Backup,Value=Daily
```

### Lab 3: Lambda@Edge for Dynamic Content

**Objective:** Implement A/B testing and security headers with Lambda@Edge.

```javascript
// a-b-testing-viewer-request.js
'use strict';

exports.handler = async (event) => {
    const request = event.Records[0].cf.request;
    const headers = request.headers;

    // Check if user already has A/B test cookie
    const cookies = headers.cookie || [];
    let experimentGroup = null;

    for (let cookie of cookies) {
        const cookieValue = cookie.value;
        const match = cookieValue.match(/experiment=([AB])/);
        if (match) {
            experimentGroup = match[1];
            break;
        }
    }

    // Assign group if not set
    if (!experimentGroup) {
        // 50/50 split
        experimentGroup = Math.random() < 0.5 ? 'A' : 'B';
    }

    // Route to different origins based on group
    if (experimentGroup === 'B') {
        // Modify request to use variant B
        request.origin = {
            custom: {
                domainName: 'variant-b.example.com',
                port: 443,
                protocol: 'https',
                path: '',
                sslProtocols: ['TLSv1.2'],
                readTimeout: 30,
                keepaliveTimeout: 5,
                customHeaders: {}
            }
        };
    }

    // Add header to identify group (for analytics)
    headers['x-experiment-group'] = [{ value: experimentGroup }];

    return request;
};
```

```javascript
// security-headers-viewer-response.js
'use strict';

exports.handler = async (event) => {
    const response = event.Records[0].cf.response;
    const headers = response.headers;

    // Add security headers
    headers['strict-transport-security'] = [{
        key: 'Strict-Transport-Security',
        value: 'max-age=31536000; includeSubDomains; preload'
    }];

    headers['content-security-policy'] = [{
        key: 'Content-Security-Policy',
        value: "default-src 'self'; script-src 'self' 'unsafe-inline' cdn.example.com; style-src 'self' 'unsafe-inline'; img-src 'self' data: https:;"
    }];

    headers['x-content-type-options'] = [{
        key: 'X-Content-Type-Options',
        value: 'nosniff'
    }];

    headers['x-frame-options'] = [{
        key: 'X-Frame-Options',
        value: 'DENY'
    }];

    headers['x-xss-protection'] = [{
        key: 'X-XSS-Protection',
        value: '1; mode=block'
    }];

    headers['referrer-policy'] = [{
        key: 'Referrer-Policy',
        value: 'strict-origin-when-cross-origin'
    }];

    // Add experiment cookie if not present
    const request = event.Records[0].cf.request;
    const requestHeaders = request.headers;
    const experimentGroup = requestHeaders['x-experiment-group'] 
        ? requestHeaders['x-experiment-group'][0].value 
        : 'A';

    headers['set-cookie'] = [{
        key: 'Set-Cookie',
        value: `experiment=${experimentGroup}; Path=/; Secure; HttpOnly; Max-Age=86400`
    }];

    return response;
};
```

**Deploy Lambda@Edge:**

```bash
# Package Lambda function
zip function.zip viewer-request.js

# Create IAM role for Lambda@Edge
cat > trust-policy.json <<EOF
{
  "Version": "2012-10-17",
  "Statement": [{
    "Effect": "Allow",
    "Principal": {
      "Service": [
        "lambda.amazonaws.com",
        "edgelambda.amazonaws.com"
      ]
    },
    "Action": "sts:AssumeRole"
  }]
}
EOF

ROLE_ARN=$(aws iam create-role \
    --role-name LambdaEdgeExecutionRole \
    --assume-role-policy-document file://trust-policy.json \
    --query 'Role.Arn' \
    --output text)

# Attach basic execution policy
aws iam attach-role-policy \
    --role-name LambdaEdgeExecutionRole \
    --policy-arn arn:aws:iam::aws:policy/service-role/AWSLambdaBasicExecutionRole

# Create Lambda function (must be in us-east-1)
FUNCTION_ARN=$(aws lambda create-function \
    --region us-east-1 \
    --function-name ABTestingViewerRequest \
    --runtime nodejs18.x \
    --role $ROLE_ARN \
    --handler viewer-request.handler \
    --zip-file fileb://function.zip \
    --timeout 5 \
    --memory-size 128 \
    --query 'FunctionArn' \
    --output text)

# Publish version (Lambda@Edge requires versioned functions)
VERSION_ARN=$(aws lambda publish-version \
    --region us-east-1 \
    --function-name ABTestingViewerRequest \
    --query 'FunctionArn' \
    --output text)

# Associate with CloudFront distribution
aws cloudfront update-distribution \
    --id $DISTRIBUTION_ID \
    --distribution-config '{
      ...
      "DefaultCacheBehavior": {
        ...
        "LambdaFunctionAssociations": {
          "Quantity": 1,
          "Items": [{
            "LambdaFunctionARN": "'$VERSION_ARN'",
            "EventType": "viewer-request",
            "IncludeBody": false
          }]
        }
      }
    }'
```

### Lab 1: Basic Domain Setup with Multiple Record Types

```bash
# Create hosted zone
aws route53 create-hosted-zone \
    --name example.com \
    --caller-reference $(date +%s) \
    --hosted-zone-config Comment="Production domain"

# Create A record for root domain
aws route53 change-resource-record-sets \
    --hosted-zone-id Z1234567890ABC \
    --change-batch '{
      "Changes": [{
        "Action": "CREATE",
        "ResourceRecordSet": {
          "Name": "example.com",
          "Type": "A",
          "TTL": 300,
          "ResourceRecords": [{"Value": "192.0.2.1"}]
        }
      }]
    }'

# Create www subdomain pointing to same IP
aws route53 change-resource-record-sets \
    --hosted-zone-id Z1234567890ABC \
    --change-batch '{
      "Changes": [{
        "Action": "CREATE",
        "ResourceRecordSet": {
          "Name": "www.example.com",
          "Type": "A",
          "TTL": 300,
          "ResourceRecords": [{"Value": "192.0.2.1"}]
        }
      }]
    }'
```

### Lab 1: SQS Standard Queue with DLQ

```python
import boto3

sqs = boto3.client('sqs')

# Create dead-letter queue
dlq_response = sqs.create_queue(
    QueueName='orders-dlq',
    Attributes={
        'MessageRetentionPeriod': '1209600'  # 14 days
    }
)
dlq_url = dlq_response['QueueUrl']
dlq_arn = sqs.get_queue_attributes(
    QueueUrl=dlq_url,
    AttributeNames=['QueueArn']
)['Attributes']['QueueArn']

# Create main queue with DLQ
main_response = sqs.create_queue(
    QueueName='orders',
    Attributes={
        'VisibilityTimeout': '60',
        'ReceiveMessageWaitTimeSeconds': '20',  # Long polling
        'RedrivePolicy': json.dumps({
            'deadLetterTargetArn': dlq_arn,
            'maxReceiveCount': '3'
        })
    }
)
queue_url = main_response['QueueUrl']
```

### Lab 2: Step Functions State Machine

```json
{
  "Comment": "Order processing workflow",
  "StartAt": "ValidateOrder",
  "States": {
    "ValidateOrder": {
      "Type": "Task",
      "Resource": "arn:aws:lambda:us-east-1:123456789012:function:validate-order",
      "Next": "ProcessPayment"
    },
    "ProcessPayment": {
      "Type": "Task",
      "Resource": "arn:aws:lambda:us-east-1:123456789012:function:process-payment",
      "Retry": [{
        "ErrorEquals": ["States.TaskFailed"],
        "IntervalSeconds": 2,
        "MaxAttempts": 3,
        "BackoffRate": 2.0
      }],
      "Catch": [{
        "ErrorEquals": ["PaymentDeclined"],
        "Next": "PaymentFailed"
      }],
      "Next": "FulfillOrder"
    },
    "FulfillOrder": {
      "Type": "Parallel",
      "Branches": [
        {
          "StartAt": "UpdateInventory",
          "States": {
            "UpdateInventory": {
              "Type": "Task",
              "Resource": "arn:aws:lambda:...:function:update-inventory",
              "End": true
            }
          }
        },
        {
          "StartAt": "SendConfirmation",
          "States": {
            "SendConfirmation": {
              "Type": "Task",
              "Resource": "arn:aws:lambda:...:function:send-email",
              "End": true
            }
          }
        }
      ],
      "Next": "OrderComplete"
    },
    "OrderComplete": {
      "Type": "Succeed"
    },
    "PaymentFailed": {
      "Type": "Fail",
