        resource_type = job['ResourceType']
        status = job['State']
        created_date = job['CreationDate']

        # Extract resource name from ARN
        resource_name = resource_arn.split('/')[-1] if '/' in resource_arn else resource_arn.split(':')[-1]

        status_icon = {
            'COMPLETED': '✓',
            'RUNNING': '⟳',
            'FAILED': '✗',
            'ABORTED': '✗'
        }.get(status, '?')

